<article class="article"><header><div class="date"><?= e(substr((string)$post['published_at'],0,10)) ?> · <?= e($post['author_name']) ?></div><h1><?= e($post['title']) ?></h1><?php if($post['excerpt']):?><p class="lead"><?= e($post['excerpt']) ?></p><?php endif;?></header><?php if(!empty($post['featured_media_id'])):?><img class="featured" src="/media/<?= (int)$post['featured_media_id'] ?>" alt=""><?php endif;?><div class="prose"><?= $post['body'] ?></div><?php if($terms):?><div class="terms"><?php foreach($terms as $t):?><a href="/<?= $t['type']==='category'?'category':'tag' ?>/<?= e($t['slug']) ?>"><?= $t['type']==='tag'?'#':'' ?><?= e($t['name']) ?></a><?php endforeach;?></div><?php endif;?></article>